import importlib.util
import json
from pathlib import Path

SCRIPT = Path(__file__).resolve().parents[1] / "scripts" / "instruction_forms_issue.py"
spec = importlib.util.spec_from_file_location("instruction_forms_issue", SCRIPT)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

REPORT = {
    "catalog_version": 1,
    "instructions": 10,
    "unknown_forms": [
        {"form": "§N skal annulleres.", "count": 2, "examples": [{"act": "lov/2026-01-01-1", "instruction": "§ 4 skal annulleres."}]},
        {"form": "§N blir tomt.", "count": 1, "examples": [{"act": "lov/2026-01-01-2", "instruction": "§ 9 blir tomt."}]},
    ],
}


class FakeApi:
    def __init__(self, issues=None, comments=None):
        self.issues = issues or []
        self.comments = comments or []
        self.calls = []

    def __call__(self, method, url, token, payload=None):
        self.calls.append((method, url, payload))
        if method == "GET" and url.endswith("per_page=100") and "/issues?" in url:
            return self.issues
        if method == "GET" and "/comments" in url:
            return self.comments
        if method == "GET" and "/labels/" in url:
            return {"name": "parser"}
        if method == "POST" and url.endswith("/issues"):
            return {"html_url": "https://github.com/o/r/issues/9"}
        return None


def test_no_unknown_forms_means_no_write(monkeypatch):
    fake = FakeApi()
    monkeypatch.setattr(module, "api", fake)
    result = module.sync({"catalog_version": 1, "instructions": 1, "unknown_forms": []}, "o/r", "t", "run")
    assert result["action"] == "none"
    assert all(method == "GET" for method, _, _ in fake.calls)


def test_creates_one_labelled_issue_with_every_form(monkeypatch):
    fake = FakeApi()
    monkeypatch.setattr(module, "api", fake)
    result = module.sync(REPORT, "o/r", "t", "https://run")
    assert result == {"action": "created", "issue": "https://github.com/o/r/issues/9", "forms": 2}
    method, url, payload = fake.calls[-1]
    assert (method, url) == ("POST", "https://api.github.com/repos/o/r/issues")
    assert payload["title"] == module.TITLE and payload["labels"] == ["parser"]
    assert "- `§N skal annulleres.` (2)" in payload["body"]
    assert "- `§N blir tomt.` (1)" in payload["body"]
    assert payload["body"].rstrip().endswith("_Generated by [Claude Code](https://claude.ai/code)_")


def test_comments_only_with_forms_not_already_listed(monkeypatch):
    existing = {"title": module.TITLE, "html_url": "https://github.com/o/r/issues/3",
                "comments_url": "https://api.github.com/repos/o/r/issues/3/comments",
                "body": "- `§N skal annulleres.` (2) — x"}
    fake = FakeApi(issues=[existing])
    monkeypatch.setattr(module, "api", fake)
    result = module.sync(REPORT, "o/r", "t", "https://run")
    assert result["action"] == "commented" and result["new_forms"] == 1
    method, url, payload = fake.calls[-1]
    assert (method, url) == ("POST", existing["comments_url"])
    assert "`§N blir tomt.` (1)" in payload["body"] and "annulleres" not in payload["body"]


def test_unchanged_when_all_forms_are_known_from_body_or_comments(monkeypatch):
    existing = {"title": module.TITLE, "html_url": "https://github.com/o/r/issues/3",
                "comments_url": "https://api.github.com/repos/o/r/issues/3/comments",
                "body": "- `§N skal annulleres.` (2) — x"}
    fake = FakeApi(issues=[existing], comments=[{"body": "- `§N blir tomt.` (1) — y"}])
    monkeypatch.setattr(module, "api", fake)
    result = module.sync(REPORT, "o/r", "t", "https://run")
    assert result["action"] == "unchanged"
    assert all(method == "GET" for method, _, _ in fake.calls)


def test_main_reads_report_and_prints_result(monkeypatch, tmp_path, capsys):
    report = tmp_path / "forms.json"
    report.write_text(json.dumps(REPORT), encoding="utf-8")
    monkeypatch.setenv("GITHUB_TOKEN", "t")
    monkeypatch.setattr(module, "api", FakeApi())
    assert module.main(["--report", str(report), "--repository", "o/r", "--run-url", "u"]) == 0
    assert json.loads(capsys.readouterr().out)["action"] == "created"
